        \gJ[\cev \lambda^\varphi_t(\cdot, \vy_t^{(k)})] = \dfrac{\gJ[\cev \lambda^\varphi_t(\cdot, \vy^{\mathrm{ref}})]}{\hat s_{T-t}^{\mathrm{jump}}(\vy^{\mathrm{ref}}, \vy_t^{(k)})},
    \end{equation*}
